-- ProTrack ATS — Supabase schema (PostgreSQL)
create extension if not exists pgcrypto;
create type public.app_role as enum ('Administratrice','Responsable RH','Responsable concerné');
create type public.application_stage as enum ('Nouvelle candidature','Présélection','En attente d’évaluation','Entretien programmé','Entretien réalisé','Décision finale','Acceptée','Rejetée');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text not null, role public.app_role not null default 'Responsable RH', created_at timestamptz not null default now());
create table public.jobs(id uuid primary key default gen_random_uuid(), title text not null, department text not null, location text, description text, education text, skills text[] not null default '{}', experience_years numeric not null default 0, availability text, requirements text, status text not null default 'Ouverte' check(status in ('Ouverte','Brouillon','Clôturée')), published_at date default current_date, deadline date, weights jsonb not null default '{"formation":25,"technique":30,"experience":20,"motivation":10,"disponibilite":5,"salaire":10}', thresholds jsonb not null default '{"recommended":75,"review":50}', owner_id uuid references public.profiles(id), created_at timestamptz not null default now(), check ((weights->>'formation')::numeric+(weights->>'technique')::numeric+(weights->>'experience')::numeric+(weights->>'motivation')::numeric+(weights->>'disponibilite')::numeric+(weights->>'salaire')::numeric=100));
create table public.job_members(job_id uuid references public.jobs(id) on delete cascade, user_id uuid references public.profiles(id) on delete cascade, can_evaluate boolean not null default true, primary key(job_id,user_id));
create table public.candidates(id uuid primary key default gen_random_uuid(), full_name text not null, email text, phone text, city text, education text, experience_years numeric default 0, skills text[] not null default '{}', languages text[] not null default '{}', created_at timestamptz not null default now());
create unique index candidates_email_lower_unique on public.candidates(lower(email)) where email is not null and email<>'';
create table public.applications(id uuid primary key default gen_random_uuid(), candidate_id uuid not null references public.candidates(id) on delete restrict, job_id uuid not null references public.jobs(id) on delete restrict, stage public.application_stage not null default 'Nouvelle candidature', applied_at timestamptz not null default now(), score numeric, ai_summary text, strengths text[] not null default '{}', missing_skills text[] not null default '{}', source text, created_by uuid references public.profiles(id), unique(candidate_id,job_id));
create table public.resumes(id uuid primary key default gen_random_uuid(), candidate_id uuid not null references public.candidates(id) on delete cascade, application_id uuid references public.applications(id) on delete cascade, storage_path text not null, original_filename text not null, mime_type text not null default 'application/pdf', uploaded_by uuid references public.profiles(id), uploaded_at timestamptz not null default now());
create table public.application_scores(id uuid primary key default gen_random_uuid(), application_id uuid not null references public.applications(id) on delete cascade, criterion text not null check(criterion in ('formation','technique','experience','motivation','disponibilite','salaire')), score numeric check(score between 0 and 10), origin text not null default 'human' check(origin in ('ai','human')), comment text, author_id uuid references public.profiles(id), created_at timestamptz not null default now(), unique(application_id,criterion,origin));
create table public.interviews(id uuid primary key default gen_random_uuid(), application_id uuid not null references public.applications(id) on delete cascade, scheduled_at timestamptz not null, interview_type text not null default 'Présentiel', status text not null default 'Prévu' check(status in ('Prévu','Réalisé','Annulé')), report text, created_by uuid references public.profiles(id), created_at timestamptz not null default now());
create table public.interview_participants(interview_id uuid references public.interviews(id) on delete cascade, user_id uuid references public.profiles(id) on delete cascade, primary key(interview_id,user_id));
create table public.evaluations(id uuid primary key default gen_random_uuid(), application_id uuid not null references public.applications(id) on delete cascade, author_id uuid not null references public.profiles(id), ratings jsonb not null default '{}', comment text, created_at timestamptz not null default now());
create table public.comments(id uuid primary key default gen_random_uuid(), application_id uuid not null references public.applications(id) on delete cascade, author_id uuid not null references public.profiles(id), body text not null, created_at timestamptz not null default now());
create table public.stage_history(id uuid primary key default gen_random_uuid(), application_id uuid not null references public.applications(id) on delete cascade, old_stage public.application_stage, new_stage public.application_stage not null, changed_by uuid references public.profiles(id), changed_at timestamptz not null default now());
create table public.audit_logs(id uuid primary key default gen_random_uuid(), actor_id uuid references public.profiles(id), action text not null, entity_type text not null, entity_id uuid, details jsonb not null default '{}', created_at timestamptz not null default now());
create or replace function public.current_role() returns public.app_role language sql stable security definer set search_path=public as $$ select role from public.profiles where id=auth.uid() $$;
create or replace function public.can_access_job(target_job uuid) returns boolean language sql stable security definer set search_path=public as $$ select public.current_role() in ('Administratrice','Responsable RH') or exists(select 1 from public.job_members where job_id=target_job and user_id=auth.uid()) $$;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select public.current_role()='Administratrice' $$;
-- Enable RLS on all user-facing tables
alter table public.profiles enable row level security; alter table public.jobs enable row level security; alter table public.job_members enable row level security; alter table public.candidates enable row level security; alter table public.applications enable row level security; alter table public.resumes enable row level security; alter table public.application_scores enable row level security; alter table public.interviews enable row level security; alter table public.interview_participants enable row level security; alter table public.evaluations enable row level security; alter table public.comments enable row level security; alter table public.stage_history enable row level security; alter table public.audit_logs enable row level security;
create policy "profile self or admin" on public.profiles for select using(id=auth.uid() or public.is_admin());
create policy "admin manages profiles" on public.profiles for all using(public.is_admin()) with check(public.is_admin());
create policy "jobs visible by role" on public.jobs for select using(public.can_access_job(id));
create policy "admin and HR manage jobs" on public.jobs for all using(public.current_role() in ('Administratrice','Responsable RH')) with check(public.current_role() in ('Administratrice','Responsable RH'));
create policy "job members visible in scope" on public.job_members for select using(public.can_access_job(job_id));
create policy "admin manages job members" on public.job_members for all using(public.is_admin()) with check(public.is_admin());
create policy "candidate records scoped through application" on public.candidates for select using(exists(select 1 from public.applications a where a.candidate_id=id and public.can_access_job(a.job_id)));
create policy "HR admin insert candidates" on public.candidates for insert with check(public.current_role() in ('Administratrice','Responsable RH'));
create policy "HR admin update candidates" on public.candidates for update using(public.current_role() in ('Administratrice','Responsable RH')) with check(public.current_role() in ('Administratrice','Responsable RH'));
create policy "applications scoped" on public.applications for select using(public.can_access_job(job_id));
create policy "HR admin manage applications" on public.applications for all using(public.current_role() in ('Administratrice','Responsable RH')) with check(public.current_role() in ('Administratrice','Responsable RH'));
create policy "resumes scoped" on public.resumes for select using(exists(select 1 from public.applications a where a.id=application_id and public.can_access_job(a.job_id)));
create policy "HR admin manage resumes" on public.resumes for all using(public.current_role() in ('Administratrice','Responsable RH')) with check(public.current_role() in ('Administratrice','Responsable RH'));
create policy "scores scoped" on public.application_scores for select using(exists(select 1 from public.applications a where a.id=application_id and public.can_access_job(a.job_id)));
create policy "authorized users write scores" on public.application_scores for insert with check(exists(select 1 from public.applications a where a.id=application_id and public.can_access_job(a.job_id)) and public.current_role() in ('Administratrice','Responsable RH'));
create policy "HR admin update scores" on public.application_scores for update using(public.current_role() in ('Administratrice','Responsable RH')) with check(public.current_role() in ('Administratrice','Responsable RH'));
create policy "interviews scoped" on public.interviews for select using(exists(select 1 from public.applications a where a.id=application_id and public.can_access_job(a.job_id)));
create policy "HR admin manage interviews" on public.interviews for all using(public.current_role() in ('Administratrice','Responsable RH')) with check(public.current_role() in ('Administratrice','Responsable RH'));
create policy "participants scoped" on public.interview_participants for select using(exists(select 1 from public.interviews i join public.applications a on a.id=i.application_id where i.id=interview_id and public.can_access_job(a.job_id)));
create policy "participants manage by HR" on public.interview_participants for all using(public.current_role() in ('Administratrice','Responsable RH')) with check(public.current_role() in ('Administratrice','Responsable RH'));
create policy "evaluations scoped" on public.evaluations for select using(exists(select 1 from public.applications a where a.id=application_id and public.can_access_job(a.job_id)));
create policy "authorized evaluation insert" on public.evaluations for insert with check(exists(select 1 from public.applications a where a.id=application_id and public.can_access_job(a.job_id)));
create policy "comments scoped" on public.comments for select using(exists(select 1 from public.applications a where a.id=application_id and public.can_access_job(a.job_id)));
create policy "authorized comments insert" on public.comments for insert with check(exists(select 1 from public.applications a where a.id=application_id and public.can_access_job(a.job_id)));
create policy "history scoped" on public.stage_history for select using(exists(select 1 from public.applications a where a.id=application_id and public.can_access_job(a.job_id)));
create policy "HR admin writes history" on public.stage_history for insert with check(public.current_role() in ('Administratrice','Responsable RH'));
create policy "audit admin read" on public.audit_logs for select using(public.is_admin());
create policy "authenticated audit insert" on public.audit_logs for insert with check(actor_id=auth.uid());
-- Create a private Storage bucket manually or run this once in SQL editor:
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('candidate-cvs','candidate-cvs',false,10485760,array['application/pdf']) on conflict(id) do nothing;
create policy "CV read in authorized job scope" on storage.objects for select using(bucket_id='candidate-cvs' and exists(select 1 from public.resumes r join public.applications a on a.id=r.application_id where r.storage_path=name and public.can_access_job(a.job_id)));
create policy "HR upload CV" on storage.objects for insert with check(bucket_id='candidate-cvs' and public.current_role() in ('Administratrice','Responsable RH'));
